import{_ as a,o as t,c as o,a2 as r}from"./chunks/framework.gtmkOXzY.js";const g=JSON.parse('{"title":"Systems","description":"","frontmatter":{},"headers":[],"relativePath":"ms-flightsim/systems.md","filePath":"ms-flightsim/systems.md","lastUpdated":null}'),n={name:"ms-flightsim/systems.md"};function i(s,e,l,c,d,h){return t(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="systems" tabindex="-1">Systems <a class="header-anchor" href="#systems" aria-label="Permalink to &quot;Systems&quot;">​</a></h1><p>Beyond the missions, these systems run the airport. Each can be tuned or switched off in its own config block.</p><h2 id="air-traffic-control" tabindex="-1">Air traffic control <a class="header-anchor" href="#air-traffic-control" aria-label="Permalink to &quot;Air traffic control&quot;">​</a></h2><ul><li>Pilots press <strong>F10</strong> in the aircraft for the ATC menu: request take-off and landing (runway or helipad), plus Ground Services and the VIP limousine. Flight plans are filed in the tablet&#39;s <strong>Flight Plan</strong> tab. Runways lock while in use.</li><li>Players on the pilot job at grade 2 or higher (<code>Config.ATCDuty.atcMinGrade</code>) go on duty at the airport&#39;s tower console. Each airport has one controller, signed off 15 seconds after leaving the airport or on disconnect. In open-access mode only admins can take ATC duty.</li><li><strong>Tower console</strong>: a three-screen radar on TV props. Press <strong>E</strong> (rebindable) to sit, use the mouse to operate it, <strong>A/D/W</strong> to look at the left, right and main screen, <strong>S</strong> to step back, and <strong>Backspace</strong> to leave. Admins place it with <code>/atcscope place</code> or the <strong>Screens</strong> tab.</li><li>While a controller is on duty, flying a job without clearance pays half (<code>Config.Payouts.noATCClearancePayMult</code>). With no controller on duty, plans are approved automatically.</li><li><strong>ATC voice</strong>: pre-recorded English voice lines, included and free to run. See <a href="./atc">Air traffic control</a>.</li></ul><h2 id="ai-traffic-and-ground-services" tabindex="-1">AI traffic and ground services <a class="header-anchor" href="#ai-traffic-and-ground-services" aria-label="Permalink to &quot;AI traffic and ground services&quot;">​</a></h2><ul><li>AI aircraft park at real stands, shut down and call for ground crew. They appear only when crew are signed on, and are removed when the job is done.</li><li>Out of the box they never taxi or fly. Flying AI (pushback, taxi, departure, approach, go-around) is a beta you enable with <code>Config.AITraffic.groundOnly = false</code>. Set the amount with <code>/aitraffic preset light|medium|heavy</code>.</li><li><strong>Ground crew</strong> sign on at the board (<strong>E</strong>), claim a job, and get the right ground vehicle for it. Pilots can also request services for their own aircraft.</li><li><strong>Taxi network</strong>: AI follow a taxiway graph. LSIA ships traced; admins draw other airports in game with <code>/airportnav</code>, and drawn layouts survive updates.</li></ul><h2 id="companies" tabindex="-1">Companies <a class="header-anchor" href="#companies" aria-label="Permalink to &quot;Companies&quot;">​</a></h2><ul><li><strong>Main company</strong>: captains (top pilot grade) manage the company fund, employees and salaries in the tablet <strong>Company</strong> tab. With <code>Config.CompanyBridge.mode = &#39;society&#39;</code> the fund is your ESX society account, so esx_billing invoices land in it.</li><li><strong>Sub-companies</strong>: any licensed pilot who owns an aircraft can found one ($25,000). They level up through 20 levels, hire AI pilots, maintain up to 10 aircraft, and dispatch real AI flights carrying their tail logo. Headquarters takes a 15% cut.</li></ul><h2 id="cockpit-and-flight-model" tabindex="-1">Cockpit and flight model <a class="header-anchor" href="#cockpit-and-flight-model" aria-label="Permalink to &quot;Cockpit and flight model&quot;">​</a></h2><ul><li>Movable, resizable PFD/HUD with attitude indicator, TAWS/GPWS, stall warnings and engine on/off.</li><li>Autopilot with heading bug and altitude selector (up to 8,500 ft), autoland for planes and auto-hover for helicopters.</li><li><strong>TCAS</strong> warns of nearby traffic: it scans 2,500 m around a plane in the air (400 m on the ground; 1,500 m / 300 m for helicopters).</li><li><strong>Wind</strong> is the same for everyone on the server (3–18 knots plus gusts by default; weather profiles can raise it) and drifts the aircraft sideways.</li><li><strong>Malfunctions</strong> can occur in flight (3% chance every 30 seconds, more with poor maintenance): stuck gear, fuel leak, engine failure, electrical or hydraulic failure.</li><li><strong>Airspace</strong>: altitude and no-fly zones push aircraft out and add strikes; police, ambulance and fire are exempt from them. Restricted zones send escort jets; only medevac, firefighting and water-bomber job aircraft and emergency landings are exempt from those.</li><li><strong>Flight recorder</strong>: every flight is logged with route, duration and approach.</li></ul>',10)])])}const u=a(n,[["render",i]]);export{g as __pageData,u as default};
